String sendMessage(String deviceId, String phone, String message, boolean isForwarded, int duration) {
    try {
        JSONObject body = new JSONObject();
        body.put("phone", phone);
        body.put("message", message);
        body.put("is_forwarded", isForwarded);
        body.put("duration", duration);

        String response = makeHttpRequest("/send/message", "POST", body.toString(), deviceId);
        addResult("    Response: " + (response != null ? response : "null"));
        return response;
    } catch (Exception e) {
        addLog("Error sending message: " + e.getMessage());
        addResult("    ERROR: " + e.getMessage());
        return null;
    }
}

String sendPoll(String deviceId, String phone, String question, JSONArray options, int maxAnswer, long endMinutes) {
    try {
        JSONObject body = new JSONObject();
        body.put("phone", phone);
        body.put("question", question);
        body.put("options", options);
        body.put("max_answer", maxAnswer);
        if (phone.endsWith("@g.us") && endMinutes > 0 && endMinutes <= 525599) {
            body.put("end_time", System.currentTimeMillis() + endMinutes * 60000L);
        }

        String response = makeHttpRequest("/send/poll", "POST", body.toString(), deviceId);
        addResult("    Response: " + (response != null ? response : "null"));
        return response;
    } catch (Exception e) {
        addLog("Error sending poll: " + e.getMessage());
        addResult("    ERROR: " + e.getMessage());
        return null;
    }
}

String sendTextStatus(String deviceId, String message, boolean isForwarded) {
    try {
        JSONObject body = new JSONObject();
        body.put("phone", "status@broadcast");
        body.put("message", message);
        body.put("is_forwarded", isForwarded);

        String response = makeHttpRequest("/send/message", "POST", body.toString(), deviceId);
        addResult("    Response: " + (response != null ? response : "null"));
        return response;
    } catch (Exception e) {
        addLog("Error sending text status: " + e.getMessage());
        addResult("    ERROR: " + e.getMessage());
        return null;
    }
}

boolean isResponseSuccess(String response) {
    if (response == null) return false;
    try {
        JSONObject jsonResponse = new JSONObject(response);
        String code = jsonResponse.optString("code", "");
        return code.equals("SUCCESS");
    } catch (Exception e) {
        return response.contains("SUCCESS");
    }
}

int updateAllJsonFilesWithNewDevices(Map newDevices) {
    int updatedFiles = 0;

    for (int f = 0; f < jsonFiles.length; f++) {
        String jsonFilePath = jsonFiles[f];
        String fileName = fileNames[f];
        String jsonContent = readJsonFile(jsonFilePath);
        if (jsonContent == null) continue;
        if (jsonContent.matches("\\s*\\[\\s*\\]\\s*")) continue;

        try {
            JSONObject root = new JSONObject(jsonContent);
            if (!root.has("devices")) continue;

            JSONArray devicesArray = root.getJSONArray("devices");
            boolean fileModified = false;

            for (int i = 0; i < devicesArray.length(); i++) {
                JSONObject deviceObj = devicesArray.getJSONObject(i);
                String oldDeviceId = deviceObj.getString("device_id");
                String phoneNumber = deviceObj.getString("device_phone");

                if (newDevices.containsKey(phoneNumber)) {
                    String newDeviceId = (String) newDevices.get(phoneNumber);
                    if (!oldDeviceId.equals(newDeviceId)) {
                        deviceObj.put("device_id", newDeviceId);
                        fileModified = true;
                        addLog("  Updated device " + phoneNumber + ": " + oldDeviceId + " -> " + newDeviceId);
                    }
                }
            }

            if (root.has("items")) {
                JSONArray itemsArray = root.getJSONArray("items");
                for (int i = 0; i < itemsArray.length(); i++) {
                    JSONObject item = itemsArray.getJSONObject(i);
                    if (item.has("device_ids")) {
                        JSONArray itemDeviceIds = item.getJSONArray("device_ids");
                        for (int j = 0; j < itemDeviceIds.length(); j++) {
                            JSONObject deviceIdObj = itemDeviceIds.getJSONObject(j);
                            String oldDeviceId = deviceIdObj.getString("device_id");
                            String phoneNumber = deviceIdObj.optString("device_phone", "");

                            if (phoneNumber.length() > 0 && newDevices.containsKey(phoneNumber)) {
                                String newDeviceId = (String) newDevices.get(phoneNumber);
                                if (!oldDeviceId.equals(newDeviceId)) {
                                    deviceIdObj.put("device_id", newDeviceId);
                                    fileModified = true;
                                    addLog("  Updated device in items: " + phoneNumber + ": " + oldDeviceId + " -> " + newDeviceId);
                                }
                            }
                        }
                    }
                }
            }

            // Mantém também os dispositivos dos cartões de campanha sincronizados.
            if (root.has("campaigns")) {
                JSONArray campaigns = root.optJSONArray("campaigns");
                if (campaigns != null) for (int c = 0; c < campaigns.length(); c++) {
                    JSONArray campaignDevices = campaigns.getJSONObject(c).optJSONArray("device_ids");
                    if (campaignDevices == null) continue;
                    for (int d = 0; d < campaignDevices.length(); d++) {
                        JSONObject obj = campaignDevices.getJSONObject(d);
                        String phone = obj.optString("device_phone", "");
                        if (phone.length() > 0 && newDevices.containsKey(phone)) {
                            String updated = (String) newDevices.get(phone);
                            if (!updated.equals(obj.optString("device_id", ""))) { obj.put("device_id", updated); fileModified = true; }
                        }
                    }
                }
            }

            if (fileModified) {
                writeJsonFile(jsonFilePath, root.toString(2));
                updatedFiles++;
                addLog("Updated file: " + fileName);
            }
        } catch (Exception e) {
            addLog("Error updating " + fileName + ": " + e.getMessage());
        }
    }

    return updatedFiles;
}

Map getDevicesFromHttpDataAndUpdateFiles() {
    Map deviceMap = new HashMap();
    Map phoneToDeviceId = new HashMap();

    String httpData = tasker.getVariable("http_data");

    if (httpData != null && httpData.length() > 0) {
        addLog("=== Using http_data from Tasker ===");
        try {
            JSONObject jsonData = new JSONObject(httpData);
            if (jsonData.has("results")) {
                JSONArray results = jsonData.getJSONArray("results");
                addLog("Found " + results.length() + " devices in http_data");

                for (int i = 0; i < results.length(); i++) {
                    JSONObject device = results.getJSONObject(i);
                    String state = device.optString("state", "");

                    if (state.equals("logged_in")) {
                        String id = device.getString("id");
                        String jid = device.getString("jid");
                        String phone = jid.replace("@s.whatsapp.net", "");
                        deviceMap.put(id, phone);
                        phoneToDeviceId.put(phone, id);
                        addLog("Logged device: " + id + " -> " + phone);
                    } else {
                        addLog("Device ignored (state=" + state + ")");
                    }
                }
            }
        } catch (Exception e) {
            addLog("Error parsing http_data: " + e.getMessage());
        }
    }

    if (!phoneToDeviceId.isEmpty()) {
        addLog("=== Updating JSON files with new device IDs ===");
        int updatedCount = updateAllJsonFilesWithNewDevices(phoneToDeviceId);
        addLog("Updated " + updatedCount + " out of " + jsonFiles.length + " JSON files");
    }

    if (deviceMap.isEmpty()) {
        addLog("=== http_data empty, trying local API ===");
        try {
            String response = makeHttpRequest("/devices", "GET", null, null);
            if (response != null) {
                JSONObject jsonResponse = new JSONObject(response);
                if (jsonResponse.has("results")) {
                    JSONArray results = jsonResponse.getJSONArray("results");
                    for (int i = 0; i < results.length(); i++) {
                        JSONObject device = results.getJSONObject(i);
                        String state = device.optString("state", "");
                        if (state.equals("logged_in")) {
                            String id = device.getString("id");
                            String jid = device.getString("jid");
                            String phone = jid.replace("@s.whatsapp.net", "");
                            deviceMap.put(id, phone);
                            addLog("API Device: " + id + " -> " + phone);
                        }
                    }
                }
            }
        } catch (Exception e) {
            addLog("API error: " + e.getMessage());
        }
    }

    if (deviceMap.isEmpty()) {
        addLog("=== Using devices from JSON files ===");
        for (int f = 0; f < jsonFiles.length; f++) {
            String jsonFilePath = jsonFiles[f];
            String jsonContent = readJsonFile(jsonFilePath);
            if (jsonContent == null) continue;
            if (jsonContent.matches("\\s*\\[\\s*\\]\\s*")) continue;
            try {
                JSONObject root = new JSONObject(jsonContent);
                if (root.has("devices")) {
                    JSONArray devices = root.getJSONArray("devices");
                    for (int i = 0; i < devices.length(); i++) {
                        JSONObject device = devices.getJSONObject(i);
                        String id = device.getString("device_id");
                        String phone = device.getString("device_phone");
                        deviceMap.put(id, phone);
                        addLog("File Device: " + id + " -> " + phone);
                    }
                }
            } catch (Exception e) {}
        }
    }

    addLog("Total available devices: " + deviceMap.size());
    return deviceMap;
}

String getCurrentDateTime() {
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    return sdf.format(Calendar.getInstance().getTime());
}

long getCurrentMillis() {
    return System.currentTimeMillis();
}

String getCurrentDate() {
    SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
    return sdf.format(Calendar.getInstance().getTime());
}

String getCurrentDay() {
    switch (Calendar.getInstance().get(Calendar.DAY_OF_WEEK)) {
        case Calendar.MONDAY: return "Mon";
        case Calendar.TUESDAY: return "Tue";
        case Calendar.WEDNESDAY: return "Wed";
        case Calendar.THURSDAY: return "Thu";
        case Calendar.FRIDAY: return "Fri";
        case Calendar.SATURDAY: return "Sat";
        case Calendar.SUNDAY: return "Sun";
        default: return "";
    }
}

String getCurrentTime() {
    SimpleDateFormat sdf = new SimpleDateFormat("HH:mm");
    return sdf.format(Calendar.getInstance().getTime());
}

// Verifica se existe algum item com horário já atingido e ainda não concluído.
// Não envia nem altera os arquivos; usa as mesmas chaves do processamento.
boolean hasPendingShipping(Map cache, String date, String day, String time) throws Exception {
    for (int f=0;f<jsonFiles.length;f++) {
        File file=new File(jsonFiles[f]);
        if(!file.exists()) continue;
        String text=readJsonFile(jsonFiles[f]);
        if(text==null) throw new Exception("Não foi possível ler " + fileNames[f]);
        if(text.matches("\\s*\\[\\s*\\]\\s*")) continue;
        JSONObject root=new JSONObject(text);
        JSONArray items=root.optJSONArray("items");
        if(items==null) throw new Exception("Lista de itens inválida em " + fileNames[f]);
        for(int i=0;i<items.length();i++) {
            JSONObject item=items.getJSONObject(i);
            JSONObject schedule=item.optJSONObject("schedule");
            if(!hasValidSchedule(schedule)||!isDayMatch(schedule.optJSONArray("days"),day))continue;
            String type=item.optString("type","unknown"),id;
            if(fileNames[f].equals("campaigns.json")&&item.optString("campaign_job_id","").length()>0)id=item.getString("campaign_job_id");
            else if(item.has("path"))id=item.getString("path");
            else if(item.has("message"))id=item.getString("message");
            else if(item.has("question"))id=item.getString("question");
            else id=String.valueOf(i);
            String prefix=fileNames[f]+"_"+type+"_"+String.valueOf(id.hashCode())+"_"+date+"_";
            JSONArray times=schedule.optJSONArray("times");
            if(times==null||times.length()==0){if(!cache.containsKey(prefix+"anytime"))return true;}
            else for(int j=0;j<times.length();j++){String scheduled=times.getString(j);if(time.compareTo(scheduled)>=0&&!cache.containsKey(prefix+scheduled))return true;}
        }
    }
    return false;
}

sendResults = "";
tasker.setVariable("shipping_available", "false");
// Apenas uma instância deste executor pode processar os arquivos e o cache.
RandomAccessFile executionLockFile = null;
FileChannel executionLockChannel = null;
FileLock executionLock = null;
try {
    try {
        executionLockFile = new RandomAccessFile(basePath + "send-executor.lock", "rw");
        executionLockChannel = executionLockFile.getChannel();
        try { executionLock = executionLockChannel.tryLock(); }
        catch (OverlappingFileLockException busy) { executionLock = null; }
    } catch (Exception lockError) {
        addLog("ERRO: Não foi possível proteger o executor: " + lockError.getMessage());
        tasker.setVariable("send_log", debugLog);
        tasker.setVariable("send_results", "Executor não iniciado: falha ao obter bloqueio.");
        tasker.setVariable("send_count", "0");
        tasker.setVariable("send_errors", "1");
        tasker.setVariable("send_processed", "0");
        tasker.setVariable("send_skipped", "0");
        tasker.setVariable("send_no_schedule", "0");
        return "Executor não iniciado: falha ao obter bloqueio.";
    }
    if (executionLock == null) {
        addLog("Executor já em andamento; esta execução foi ignorada.");
        tasker.setVariable("send_log", debugLog);
        tasker.setVariable("send_results", "Executor já em andamento.");
        tasker.setVariable("send_count", "0");
        tasker.setVariable("send_errors", "0");
        tasker.setVariable("send_processed", "0");
        tasker.setVariable("send_skipped", "0");
        tasker.setVariable("send_no_schedule", "0");
        return "Executor já em andamento.";
    }
