        .url(apiUrl)
        .header("User-Agent", "Tasker")
        .header("Accept", "application/vnd.github+json")
        .build();

    response = client.newCall(request).execute();

    if (!response.isSuccessful()) {
        if (response.code() == 403) {
            resultSignal = SingleSubject.create();
            myActivityConsumer = new java.util.function.Consumer() {
                accept(Object activity) {
                    final Activity currentActivity = (Activity) activity;
                    onClickListener = new DialogInterface.OnClickListener() {
                        onClick(DialogInterface dialog, int which) {
                            resultSignal.onSuccess("ok");
                        }
                    };
                    builder = new AlertDialog.Builder(currentActivity);
                    builder.setTitle("Erro de API / API Error");
                    builder.setMessage("Limite de requisições do GitHub excedido (Erro 403). Tente novamente mais tarde ou adicione um Token de Acesso Pessoal.\n\nGitHub API rate limit exceeded (Error 403). Please try again later or add a Personal Access Token.");
                    builder.setPositiveButton("OK", onClickListener);
                    dialog = builder.create();
                    dialog.setOnDismissListener(new DialogInterface.OnDismissListener() {
                        onDismiss(DialogInterface d) {
                            currentActivity.finish();
                        }
                    });
                    dialog.show();
                }
            };
            tasker.doWithActivityUntilGone(myActivityConsumer, 30000);
        }
        throw new JavaCodeException("Falha ao consultar API: " + response.code());
    }

    jsonResponse = response.body().string();

    zipUrl = null;
    parts = jsonResponse.split("\"browser_download_url\":\"");
    if (parts.length > 1) {
        for (int i = 1; i < parts.length; i++) {
            endQuote = parts[i].indexOf("\"");
            if (endQuote > 0) {
                candidateUrl = parts[i].substring(0, endQuote);
                if (candidateUrl.endsWith(".zip")) {
                    zipUrl = candidateUrl;
                    break;
                }
            }
        }
    }

    if (zipUrl == null) {
        throw new JavaCodeException("Não foi possível encontrar o link do .zip na última release.");
    }

    request = new Request.Builder().url(zipUrl).header("User-Agent", "Tasker").build();
    response = client.newCall(request).execute();
    if (!response.isSuccessful()) {
        throw new JavaCodeException("Falha no download do ZIP: " + response.code());
    }

    in = response.body().byteStream();
    zis = new ZipInputStream(in);
    extracted = false;
    buf = new byte[8192];

    try {
        while ((entry = zis.getNextEntry()) != null) {
            entryName = entry.getName();

            if (!entry.isDirectory() && entryName.indexOf("configuracao-webview-wca") >= 0 && entryName.endsWith(".html")) {
                fos = new FileOutputStream(targetFile);
                try {
                    while ((n = zis.read(buf)) != -1) {
                        fos.write(buf, 0, n);
                    }
                } finally {
                    try { fos.close(); } catch (Exception e) {}
                }
                extracted = true;
                zis.closeEntry();
                break;
            }
            zis.closeEntry();
        }
    } finally {
        try { zis.close(); } catch (Exception e) {}
        try { in.close(); } catch (Exception e) {}
        try { response.body().close(); } catch (Exception e) {}
    }

    if (!extracted) {
        throw new JavaCodeException("O arquivo HTML não foi encontrado dentro do ZIP.");
    }
}

