    }
}

if (allExist) {
    tasker.setVariable("project_exist_full", "yes");
    return "yes";
} else {
    tasker.setVariable("project_exist_full", "no");
    return "no";
}

import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import java.io.File;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.function.Consumer;
import android.app.Activity;
import android.app.AlertDialog;
import android.widget.TextView;
import android.widget.LinearLayout;
import io.reactivex.subjects.CompletableSubject;
import org.json.JSONObject;
import org.json.JSONArray;

errorLog = new ArrayList();

String urlApi = tasker.getVariable("url_project_wca");
if (urlApi == null || urlApi.equals("")) {
    errorLog.add("URL_PROJECT_WCA não definida");
    tasker.setVariable("download_error_log", errorLog.toString());
    return "Error: URL_PROJECT_WCA não definida";
}

String filePath = "/storage/emulated/0/Tasker/projects_task/projects/whats-connect-api/system/tasks-send/W_C_A_API_RECEIVER.prj.xml";
OkHttpClient client = new OkHttpClient();
String releaseJson = null;

try {
    Request request = new Request.Builder().url(urlApi).build();
    Response response = client.newCall(request).execute();
    if (response.isSuccessful()) {
        releaseJson = response.body().string();
    } else {
        errorLog.add("Falha ao buscar release: HTTP " + response.code());
        tasker.setVariable("download_error_log", errorLog.toString());
        return "Error: Falha ao buscar release";
    }
    response.close();
} catch (Exception e) {
    errorLog.add("Requisição release: " + e.getClass().getSimpleName() + " - " + e.getMessage());
    tasker.setVariable("download_error_log", errorLog.toString());
    return "Error: " + e.getMessage();
}

JSONObject release = new JSONObject(releaseJson);
JSONArray assets = release.getJSONArray("assets");
String url = null;

for (int i = 0; i < assets.length(); i++) {
    JSONObject asset = assets.getJSONObject(i);
    String name = asset.getString("name");
    String downloadUrl = asset.getString("browser_download_url");

    if (name.equals("W_C_A_API_RECEIVER.prj.xml")) {
        url = downloadUrl;
        break;
    }
}

if (url == null) {
    errorLog.add("Arquivo W_C_A_API_RECEIVER.prj.xml não encontrado no release");
    tasker.setVariable("download_error_log", errorLog.toString());
    return "Error: Arquivo não encontrado";
}

/* Só a partir daqui, com o arquivo localizado, o diálogo é exibido. */
shownSignal = CompletableSubject.create();
statusTextRef = new TextView[1];
activityRef = new Activity[1];
dialogRef = new AlertDialog[1];

dialogConsumer = new Consumer() {
    accept(Object activityObj) {
        activity = (Activity) activityObj;
        activityRef[0] = activity;

        statusText = new TextView(activity);
        statusText.setText("Baixando W_C_A_API_RECEIVER.prj.xml...");
        statusText.setPadding(48, 32, 48, 32);
        statusText.setTextSize(15);
        statusTextRef[0] = statusText;

        container = new LinearLayout(activity);
        container.setOrientation(LinearLayout.VERTICAL);
        container.addView(statusText);

        builder = new AlertDialog.Builder(activity);
        builder.setTitle("Baixando receiver do seu WCA, aguarde...");
        builder.setView(container);
        builder.setCancelable(false);
        dialog = builder.create();
        dialog.show();
        dialogRef[0] = dialog;

        shownSignal.onComplete();
    }
};

tasker.doWithActivity(dialogConsumer);
shownSignal.blockingAwait();

activity = activityRef[0];
statusText = statusTextRef[0];
dialog = dialogRef[0];

updateStatus = new Consumer() {
    accept(Object text) {
        final String msg = (String) text;
        activity.runOnUiThread(new Runnable() {
            run() {
                statusText.setText(msg);
            }
        });
    }
};

closeDialog = new Runnable() {
    run() {
        dialog.dismiss();
        activity.finish();
    }
};

try {
    File destFile = new File(filePath);
    File parentDir = destFile.getParentFile();
    if (parentDir != null && !parentDir.exists()) parentDir.mkdirs();
    if (destFile.exists()) destFile.delete();

    Request request = new Request.Builder().url(url).build();
    Response response = client.newCall(request).execute();

    if (!response.isSuccessful()) {
        errorLog.add("Download HTTP " + response.code());
        tasker.setVariable("download_error_log", errorLog.toString());
        updateStatus.accept("Erro no download");
        Thread.sleep(1500);
        activity.runOnUiThread(closeDialog);
        return "Error: Falha no download";
    }

    ResponseBody body = response.body();
    if (body == null) {
        errorLog.add("Response body vazio");
        tasker.setVariable("download_error_log", errorLog.toString());
        updateStatus.accept("Erro: resposta vazia");
        Thread.sleep(1500);
        activity.runOnUiThread(closeDialog);
        return "Error: Body vazio";
    }

    InputStream inputStream = body.byteStream();
    FileOutputStream outputStream = new FileOutputStream(destFile);

    byte[] buffer = new byte[8192];
    int bytesRead;
    while ((bytesRead = inputStream.read(buffer)) != -1) {
        outputStream.write(buffer, 0, bytesRead);
    }

    outputStream.flush();
    outputStream.close();
    inputStream.close();
    response.close();

    tasker.setVariable("download_error_log", errorLog.toString());
    updateStatus.accept("Arquivo baixado com sucesso!");
    Thread.sleep(1500);
    activity.runOnUiThread(closeDialog);
    return "Success: File downloaded";

} catch (IOException e) {
    errorLog.add("Download: " + e.getClass().getSimpleName() + " - " + e.getMessage());
    tasker.setVariable("download_error_log", errorLog.toString());
    updateStatus.accept("Erro no download");
    Thread.sleep(1500);
    activity.runOnUiThread(closeDialog);
    return "Error: " + e.getMessage();
}

import io.reactivex.functions.Consumer;
import java.util.ArrayList;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

service = tasker.getAccessibilityService();
if (service == null) {
    throw new JavaCodeException("Servico de Acessibilidade nao ativo.");
}

botoes = new String[] {
    "SIM", "YES", "OK", "S\u00cd", "S\u00cc", "OUI", "JA", "\u0414\u0410", "\u662f", "\u786e\u5b9a", "\u78ba\u5b9a",
    "SUBSTITUIR", "REPLACE", "OVERWRITE", "CONTINUAR", "CONTINUE"
};

marcadores = new String[] {
    "button1", "button2", "button3", "button_positive", "button_negative",
    "buttonPanel", "parentPanel", "alertTitle"
};

importados = new String[] {
    "IMPORTED", "IMPORTADO", "IMPORTADA", "IMPORT\u00c9", "IMPORTIERT",
    "\u0418\u041c\u041f\u041e\u0420\u0422\u0418\u0420\u041e\u0412\u0410\u041d",
    "\u5df2\u5bfc\u5165", "\u5df2\u5c0e\u5165", "\u5bfc\u5165\u6210\u529f", "\u5c0e\u5165\u6210\u529f", "\u532f\u5165\u6210\u529f"
};

projetos = new String[] {
    "PROJECT", "PROJETO", "PROYECTO", "PROJET", "PROJEKT",
    "\u041f\u0420\u041e\u0415\u041a\u0422", "\u9879\u76ee", "\u5c08\u6848", "\u9805\u76ee"
};

contem(texto, lista) {
    for (k = 0; k < lista.length; k++) {
        if (texto.contains(lista[k])) { return true; }
    }
    return false;
}

ehBotao(t) {
    for (k = 0; k < botoes.length; k++) {
        if (botoes[k].equals(t)) { return true; }
    }
    return false;
}

ehMarcador(id) {
    for (k = 0; k < marcadores.length; k++) {
        if (id.contains(marcadores[k])) { return true; }
    }
    return false;
}

ehImportado(texto) {
    return contem(texto, importados) && contem(texto, projetos);
}

clicar(node) {
    alvo = node;
    prof = 0;
    while (alvo != null && !alvo.isClickable() && prof < 6) {
        alvo = alvo.getParent();
        prof++;
    }
    if (alvo == null || !alvo.isClickable()) { return false; }
    return alvo.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);
}

porEvento = new ArrayList();

consumidor = new Consumer() {
    accept(evento) {
        textos = evento.getText();
        if (textos == null) { return; }
        for (k = 0; k < textos.size(); k++) {
            item = textos.get(k);
            if (item == null) { continue; }
            if (ehImportado(item.toString().toUpperCase().trim())) { porEvento.add("1"); }
        }
    }
};

assinatura = tasker.getAccessibilityEvents().subscribe(consumidor);

result = "timeout";
passadaMax = 0;
maiorInt = 0;
ultimoClique = 0;
intAtiv = 0;
ultimoAtiv = 0;
fator = 1.5;
inicio = System.currentTimeMillis();
ultimaAtiv = inicio;
fim = inicio + 40000;
jaClicou = false;
importadoEm = 0;
cliquesImp = 0;

android.os.SystemClock.sleep(500);

try {
    while (System.currentTimeMillis() < fim) {
        if (importadoEm == 0 && porEvento.size() > 0) {
            importadoEm = System.currentTimeMillis();
            ultimaAtiv = importadoEm;
        }

        iniPassada = System.currentTimeMillis();
        root = service.getRootInActiveWindow();

        if (root != null) {
            nodes = service.getChildrenRecursive(root);
            dialogo = false;
            clicou = false;
            naTela = false;

            for (i = 0; i < nodes.size(); i++) {
                node = nodes.get(i);
                if (node == null) { continue; }

                viewId = node.getViewIdResourceName();
                if (viewId != null && ehMarcador(viewId)) {
                    dialogo = true;
                    if (viewId.contains("button1") || viewId.contains("button_positive")) {
                        if (clicar(node)) { clicou = true; }
                    }
                }

                desc = node.getContentDescription();
                if (desc != null && ehImportado(desc.toString().toUpperCase().trim())) { naTela = true; }

                if (node.getText() == null) { continue; }
                t = node.getText().toString().toUpperCase().trim();

                if (ehImportado(t)) {
                    naTela = true;
                    continue;
                }

                if (ehBotao(t)) {
                    dialogo = true;
                    if (clicar(node)) { clicou = true; }
                }
            }

            agora = System.currentTimeMillis();
            duracao = agora - iniPassada;
            if (duracao > passadaMax) { passadaMax = duracao; }
            fator = passadaMax / 100.0;
            if (fator < 1.5) { fator = 1.5; }
            if (fator > 6) { fator = 6; }

            silFinal = 6000 * fator;
            silSem = 3000 * fator;
            if (2.5 * maiorInt > silFinal) { silFinal = 2.5 * maiorInt; }

            espAtiv = 1500 + 5 * passadaMax;
            silAtivar = 600 + 3 * duracao;
            if (1.5 * intAtiv > silAtivar) { silAtivar = 1.5 * intAtiv; }

            if (naTela && importadoEm == 0) {
                importadoEm = agora;
                ultimaAtiv = agora;
            }

            if (clicou) {
                jaClicou = true;
                if (ultimoClique > 0 && agora - ultimoClique > maiorInt && importadoEm == 0) {
                    maiorInt = agora - ultimoClique;
                }
                ultimoClique = agora;
                ultimaAtiv = agora;
                fim = agora + 25000 * fator;

                if (importadoEm > 0) {
                    cliquesImp++;
                    if (ultimoAtiv > 0 && agora - ultimoAtiv > intAtiv) { intAtiv = agora - ultimoAtiv; }
                    ultimoAtiv = agora;
                    android.os.SystemClock.sleep(100);
                    continue;
                }

                android.os.SystemClock.sleep((long) (250 * fator));
                continue;
            }

            if (dialogo) { ultimaAtiv = agora; }

            silencio = agora - ultimaAtiv;

            if (importadoEm > 0 && cliquesImp > 0 && silencio >= silAtivar) {
                result = "imported";
                break;
            }

            if (importadoEm > 0 && cliquesImp == 0 && !dialogo && agora - importadoEm >= espAtiv) {
                result = "imported";
                break;
            }

            if (importadoEm == 0 && jaClicou && silencio >= silFinal) {
                result = "imported";
                break;
            }

            if (importadoEm == 0 && !jaClicou && silencio >= silSem) {
                result = "no_dialog";
                break;
            }
        }

        if (importadoEm > 0) {
            android.os.SystemClock.sleep(50);
        } else {
            android.os.SystemClock.sleep(150);
        }
    }
} finally {
    assinatura.dispose();
}

tasker.log("Resultado: " + result + " fator: " + fator + " espAtiv: " + espAtiv);
return result;

import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import java.io.File;
import java.io.FileInputStream;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

versionFilePath = "/storage/emulated/0/Tasker/projects_task/projects/whats-connect-api/system/version";
versionFile = new File(versionFilePath);

if (!versionFile.exists()) {
    throw new JavaCodeException("Arquivo de versão não encontrado: " + versionFilePath);
}

fis = new FileInputStream(versionFile);
localVersion = "";
try {
    buf = new byte[(int) versionFile.length()];
    n = fis.read(buf);
    if (n > 0) {
        localVersion = new String(buf, 0, n, "UTF-8").trim();
    }
} finally {
    try { fis.close(); } catch (Exception e) {}
}

if (localVersion.length() == 0) {
    throw new JavaCodeException("Arquivo de versão está vazio.");
}

apiUrl = "https://api.github.com/repos/multihubandredye-prog/W-C-A_GO/releases/latest";
client = new OkHttpClient();
request = new Request.Builder()
    .url(apiUrl)
    .header("User-Agent", "Tasker")
    .header("Accept", "application/vnd.github+json")
    .build();

response = client.newCall(request).execute();
if (!response.isSuccessful()) {
    throw new JavaCodeException("Falha ao consultar API: " + response.code());
}
jsonResponse = response.body().string();

remoteVersion = null;
parts = jsonResponse.split("\"tag_name\":\"");
if (parts.length > 1) {
    endQuote = parts[1].indexOf("\"");
    if (endQuote > 0) {
        remoteVersion = parts[1].substring(0, endQuote).trim();
    }
}

if (remoteVersion == null || remoteVersion.length() == 0) {
    throw new JavaCodeException("Não foi possível obter o tag_name da última release.");
}

remoteTitle = "";
partsName = jsonResponse.split("\"name\":\"");
if (partsName.length > 1) {
    endQuoteName = partsName[1].indexOf("\"");
    if (endQuoteName > 0) {
        remoteTitle = partsName[1].substring(0, endQuoteName);
    }
}

temPalavra = false;
titleLower = remoteTitle.toLowerCase();
palavras = new String[] { "core", "ui", "full" };
for (int i = 0; i < palavras.length; i++) {
    p = palavras[i];
    idx = titleLower.indexOf(p);
    while (idx >= 0) {
        beforeOk = (idx == 0) || !Character.isLetterOrDigit(titleLower.charAt(idx - 1)) && titleLower.charAt(idx - 1) != '_';
        afterIdx = idx + p.length();
        afterOk = (afterIdx >= titleLower.length()) || !Character.isLetterOrDigit(titleLower.charAt(afterIdx)) && titleLower.charAt(afterIdx) != '_';
        if (beforeOk && afterOk) {
            temPalavra = true;
            break;
        }
        idx = titleLower.indexOf(p, idx + 1);
    }
    if (temPalavra) { break; }
}

localNorm = localVersion.toLowerCase();
remoteNorm = remoteVersion.toLowerCase();
if (localNorm.startsWith("v")) { localNorm = localNorm.substring(1); }
if (remoteNorm.startsWith("v")) { remoteNorm = remoteNorm.substring(1); }

versaoMaior = false;
if (!localNorm.equals(remoteNorm)) {
    localParts = localNorm.split("\\.");
    remoteParts = remoteNorm.split("\\.");
    maxLen = localParts.length;
    if (remoteParts.length > maxLen) { maxLen = remoteParts.length; }

    for (int i = 0; i < maxLen; i++) {
        lv = 0;
        rv = 0;
        if (i < localParts.length) {
            try { lv = Integer.parseInt(localParts[i]); } catch (Exception e) { lv = 0; }
        }
        if (i < remoteParts.length) {
            try { rv = Integer.parseInt(remoteParts[i]); } catch (Exception e) { rv = 0; }
        }
        if (rv > lv) { versaoMaior = true; break; }
        if (rv < lv) { break; }
    }
}

temUpdate = versaoMaior && temPalavra;

tasker.setVariable("new_update", temUpdate ? "true" : "false");
return temUpdate ? "true" : "false";

