import java.util.HashMap;
import java.util.Collections;
import java.util.Comparator;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

rawContactsUri = ContactsContract.RawContacts.CONTENT_URI;
rawContactsProjection = new String[]{
    ContactsContract.RawContacts._ID,
    ContactsContract.RawContacts.DISPLAY_NAME_PRIMARY,
    ContactsContract.RawContacts.ACCOUNT_TYPE
};
// Consulta automaticamente as duas contas, sem exibir diálogo.
rawContactsSelection = ContactsContract.RawContacts.ACCOUNT_TYPE + " IN (?, ?)";
rawContactsSelectionArgs = new String[]{"com.whatsapp", "com.whatsapp.w4b"};
tasker.log("Consultando contatos do WhatsApp e WhatsApp Business.");

rawContactsSortOrder = ContactsContract.RawContacts._ID + " LIMIT 3000";
contentResolver = context.getContentResolver();
whatsappContacts = new ArrayList();
rawContactsCursor = null;
try {
    rawContactsCursor = contentResolver.query(rawContactsUri, rawContactsProjection,
        rawContactsSelection, rawContactsSelectionArgs, rawContactsSortOrder);
    if (rawContactsCursor == null) {
        throw new JavaCodeException("Failed to query raw contacts. Cursor is null.");
    }
    while (rawContactsCursor.moveToNext()) {
        contact = new HashMap();
        idIndex = rawContactsCursor.getColumnIndex(ContactsContract.RawContacts._ID);
        displayNameIndex = rawContactsCursor.getColumnIndex(ContactsContract.RawContacts.DISPLAY_NAME_PRIMARY);
        accountTypeIndex = rawContactsCursor.getColumnIndex(ContactsContract.RawContacts.ACCOUNT_TYPE);
        if (idIndex != -1) contact.put("_id", new Integer(rawContactsCursor.getInt(idIndex)));
        if (displayNameIndex != -1) contact.put("display_name", rawContactsCursor.getString(displayNameIndex));
        if (accountTypeIndex != -1) contact.put("account_type", rawContactsCursor.getString(accountTypeIndex));
        whatsappContacts.add(contact);
    }
} finally {
    if (rawContactsCursor != null) rawContactsCursor.close();
}

for (i = 0; i < whatsappContacts.size(); i++) {
    contact = (HashMap) whatsappContacts.get(i);
    rawContactId = (Integer) contact.get("_id");
    if (rawContactId == null) {
        tasker.log("Skipping contact with null raw_contact_id.");
        continue;
    }
    dataCursor = null;
    try {
        dataUri = ContactsContract.Data.CONTENT_URI;
        dataProjection = new String[]{ContactsContract.Data.DATA1, ContactsContract.Data.MIMETYPE};
        dataSelection = ContactsContract.Data.RAW_CONTACT_ID + " = ? AND (" +
            ContactsContract.Data.MIMETYPE + " = ? OR " + ContactsContract.Data.MIMETYPE + " = ?)";
        dataSelectionArgs = new String[]{String.valueOf(rawContactId),
            ContactsContract.CommonDataKinds.Phone.CONTENT_ITEM_TYPE,
            "vnd.android.cursor.item/vnd.com.whatsapp.profile"};
        dataCursor = contentResolver.query(dataUri, dataProjection, dataSelection, dataSelectionArgs, null);
        if (dataCursor == null) {
            tasker.log("Failed to query data for raw contact ID: " + rawContactId + ". Cursor is null.");
            continue;
        }
        while (dataCursor.moveToNext()) {
            data1Index = dataCursor.getColumnIndex(ContactsContract.Data.DATA1);
            mimetypeIndex = dataCursor.getColumnIndex(ContactsContract.Data.MIMETYPE);
            if (data1Index != -1 && mimetypeIndex != -1) {
                data1 = dataCursor.getString(data1Index);
                mimetype = dataCursor.getString(mimetypeIndex);
                if (data1 != null && data1.length() > 0) {
                    if (ContactsContract.CommonDataKinds.Phone.CONTENT_ITEM_TYPE.equals(mimetype)) {
                        contact.put("number", data1);
                        break;
                    } else if ("vnd.android.cursor.item/vnd.com.whatsapp.profile".equals(mimetype)) {
                        if (!contact.containsKey("number")) contact.put("number", data1);
                    }
                }
            }
        }
    } finally {
        if (dataCursor != null) dataCursor.close();
    }
}

Collections.sort(whatsappContacts, new Comparator() {
    compare(Object o1, Object o2) {
        HashMap map1 = (HashMap) o1;
        HashMap map2 = (HashMap) o2;
        String name1 = (String) map1.get("display_name");
        String name2 = (String) map2.get("display_name");
        if (name1 == null && name2 == null) return 0;
        if (name1 == null) return -1;
        if (name2 == null) return 1;
        return name1.compareToIgnoreCase(name2);
    }
});

// A cena Contatos Pro WCA lê esta variável para preencher Minha Agenda.
jsonOutput = tasker.toJson(whatsappContacts, true);
tasker.setVariable("contacts_address", jsonOutput);
return jsonOutput;

import android.content.Intent;
import android.net.Uri;
import android.view.accessibility.AccessibilityNodeInfo;
import android.os.Bundle;
import java.util.List;

/* Configuração inicial */
waType = tasker.getVariable("wa_type");
packageName = (waType != null && waType.equalsIgnoreCase("whatsApp business")) ? "com.whatsapp.w4b" : "com.whatsapp";
meuCodigo = "%http_data.pair_code"; 

/* Dicionário exaustivo para o Passo 1: Botão central */
termosPasso1 = new String[]{
    /* Variações em russo */
    "Связывание устройства", "Связать устройство", "Связывание", "Связать", 
    /* Variações em inglês (US/UK) */
    "Link a device", "Link a Device", "Link device", "Link",
    /* Português/Espanhol/Italiano/Francês */
    "Conectar", "Conectar dispositivo", "Vincular", "Vincular un dispositivo", "Collega", "Lier", "Lier um appareil",
    /* Alemão/Outros */
    "Gerät", "Gerät verknüpfen", "连接", "연결", "اتصال", "डिवाइस लिंक करें", "Tautkan"
};

/* Dicionário exaustivo para o Passo 2: Link inferior */
termosPasso2 = new String[]{
    /* Variações em russo */
    "Связать по номерu телефона", "Связать по номеру", "по номеру телефона", "номер",
    /* Inglês */
    "Link with phone number", "Link with phone", "Link with Phone Number", "phone number",
    /* Português/Espanhol */
    "Conectar com número", "Conectar com número de telefone", "Vincular com número", "Número de teléfono",
    /* Outros */
    "Mit Telefonnummer", "Numéro de téléphone", "Номер телефона", "رقم الهاتف", "बिना QR कोड के लिंक करें"
};

/* 2. Abrir a tela de Dispositivos Conectados */
intent = new Intent(Intent.ACTION_VIEW);
intent.setData(Uri.parse("whatsapp://settings/linked_devices"));
intent.setPackage(packageName);
intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TOP);
try { context.startActivity(intent); } catch (Exception e) { tasker.log("Erro: " + e.getMessage()); }

/* 3. PASSO 1: Clicar no botão "Conectar um dispositivo" */
timeout1 = System.currentTimeMillis() + 15000;
clicouPrimeiro = false;
buttonId = packageName + ":id/button_open_qr_code_scanner";

while (System.currentTimeMillis() < timeout1 && !clicouPrimeiro) {
    service = tasker.getAccessibilityService();
    if (service == null) break;
    rootNode = service.getRootInActiveWindow();
    if (rootNode != null) {
        nodes = rootNode.findAccessibilityNodeInfosByViewId(buttonId);

        if (nodes == null || nodes.isEmpty()) {
            for (int i = 0; i < termosPasso1.length; i++) {
                termo = termosPasso1[i]; /* Corrigido: termosPassos1 para termosPasso1 */
                nodes = rootNode.findAccessibilityNodeInfosByText(termo);
                if (nodes != null && !nodes.isEmpty()) break;
            }
        }

        if (nodes != null && !nodes.isEmpty()) {
            node = nodes.get(0);
            tempNode = node;
            while (tempNode != null && !tempNode.isClickable()) { tempNode = tempNode.getParent(); }
            if (tempNode != null && tempNode.isClickable()) {
                tempNode.performAction(AccessibilityNodeInfo.ACTION_CLICK);
                clicouPrimeiro = true;
                tasker.log("Passo 1: Sucesso (" + node.getText() + ")");
            }
        }
        rootNode.recycle();
    }
    if (!clicouPrimeiro) Thread.sleep(500);
}

/* 4. PASSO 2: Monitorar o prompt de senha e clicar em "Conectar com número de telefone" */
clicouSegundo = false;
if (clicouPrimeiro) {
    timeout2 = System.currentTimeMillis() + 20000;
    idLinkTelefone = packageName + ":id/link_with_phone_number_button";
    /* idBotaoOk = packageName + ":id/ok_button"; Removido conforme solicitação */

    while (System.currentTimeMillis() < timeout2 && !clicouSegundo) {
        service = tasker.getAccessibilityService();
        root = (service != null) ? service.getRootInActiveWindow() : null;
        if (root != null) {
            /* A lógica para clicar no botão OK foi removida. */

            /* Procurar por "Conectar com número de telefone" */
            phoneNodes = root.findAccessibilityNodeInfosByViewId(idLinkTelefone);

            if (phoneNodes == null || phoneNodes.isEmpty()) {
                for (int i = 0; i < termosPasso2.length; i++) { /* Corrigido: termosPassos2 para termosPasso2 */
                    termo = termosPasso2[i]; /* Corrigido: termosPassos2 para termosPasso2 */
                    phoneNodes = root.findAccessibilityNodeInfosByText(termo);
                    if (phoneNodes != null && !phoneNodes.isEmpty()) break;
                }
            }

            if (phoneNodes != null && !phoneNodes.isEmpty()) {
                pNode = phoneNodes.get(0);
                while (pNode != null && !pNode.isClickable()) { pNode = pNode.getParent(); }
                if (pNode != null && pNode.isClickable()) {
                    pNode.performAction(AccessibilityNodeInfo.ACTION_CLICK);
                    clicouSegundo = true;
                    tasker.log("Passo 2: Sucesso.");
                }
            }
            root.recycle();
        }
        if (!clicouSegundo) Thread.sleep(500);
    }
}

/* 5. PASSO 3: Inserir código (universal) */
if (clicouSegundo) {
    timeout3 = System.currentTimeMillis() + 15000;
    inserido = false;
    while (System.currentTimeMillis() < timeout3 && !inserido) {
        service = tasker.getAccessibilityService();
        root = (service != null) ? service.getRootInActiveWindow() : null;
        if (root != null) {
            focusNode = root.findFocus(AccessibilityNodeInfo.FOCUS_INPUT);
            if (focusNode != null && focusNode.getClassName().toString().contains("EditText")) {
                args = new Bundle();
                args.putCharSequence("ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE", meuCodigo);
                focusNode.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, args);
                tasker.log("Passo 3: Sucesso!");
                inserido = true;
                /* Esperar 1 segundo após inserir o código para processamento antes de monitorar */
                Thread.sleep(1000); /* Alterado de 20 segundos para 1 segundo */
                focusNode.recycle();
            }
            root.recycle();
        }
        if (!inserido) Thread.sleep(1000);
    }
}

/* 6. PASSO 4: Monitorar o texto "Conectando" até desaparecer */
if (inserido) {
    timeout4 = System.currentTimeMillis() + 60000; /* 60 segundos de timeout para a conexão */
    conectandoDesapareceu = false;

    /* Dicionário exaustivo para o Passo 4: Texto "Conectando" */
    termosPasso4 = new String[]{
        "Conectando", "Connecting", "Connessione", "Connexion", "Verbinden", "Подключение", "جارٍ الاتصال", "कनेक्ट हो रहा है", "Menghubungkan"
    };

    while (System.currentTimeMillis() < timeout4 && !conectandoDesapareceu) {
        service = tasker.getAccessibilityService();
        root = (service != null) ? service.getRootInActiveWindow() : null;
        if (root != null) {
            encontrouConectando = false;
            for (int i = 0; i < termosPasso4.length; i++) {
                termo = termosPasso4[i];
                nodes = root.findAccessibilityNodeInfosByText(termo);
                if (nodes != null && !nodes.isEmpty()) {
                    encontrouConectando = true;
                    break;
                }
            }

            if (!encontrouConectando) {
                /* O texto "Conectando" desapareceu */
                conectandoDesapareceu = true;
                tasker.log("Passo 4: Texto 'Conectando' desapareceu. Sucesso!");
            } else {
                tasker.log("Passo 4: 'Conectando' ainda visível. Aguardando...");
            }
            root.recycle();
        } else {
            tasker.log("Passo 4: Root node nulo ou serviço de acessibilidade indisponível.");
        }
        if (!conectandoDesapareceu) Thread.sleep(1000); /* Esperar 1 segundo antes de verificar novamente */
    }

    if (!conectandoDesapareceu) {
        tasker.log("Passo 4: Timeout atingido. O texto 'Conectando' não desapareceu.");
    }
}

