writing = false;
startTime = System.currentTimeMillis();

try {
    uri = tasker.getVariable("sb_uri");
    if (uri == null || uri == void || uri.trim().length() == 0) {
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("sb_uri is empty");
    }
    uri = uri.trim();

    dirPath = "/storage/emulated/0/Tasker/projects_task/projects/whats-connect-api/system/user-profile-picture";
    fileName = "photo-profile.png";
    limitMs = 3000;

    if (uri.startsWith("content://")) {
        input = context.getContentResolver().openInputStream(android.net.Uri.parse(uri));
    } else if (uri.startsWith("file://")) {
        input = new java.io.FileInputStream(new java.io.File(android.net.Uri.parse(uri).getPath()));
    } else {
        input = new java.io.FileInputStream(new java.io.File(uri));
    }
    if (input == null) {
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Could not open the image");
    }
    openedAt = System.currentTimeMillis();

    dir = new java.io.File(dirPath);
    if (!dir.exists()) dir.mkdirs();

    files = dir.listFiles();
    if (files != null) {
        for (i = 0; i < files.length; i++) {
            if (files[i].isFile()) files[i].delete();
        }
    }
    cleanedAt = System.currentTimeMillis();

    state = new int[1];
    errors = new String[1];
    writing = true;

    worker = new Thread(new Runnable() {
        run() {
            try {
                output = new java.io.FileOutputStream(new java.io.File(dir, fileName));
                try {
                    android.os.FileUtils.copy(input, output);
                } finally {
                    output.close();
                }
                state[0] = 1;
            } catch (Exception e) {
                errors[0] = "" + e;
                state[0] = 2;
            }
        }
    });

    worker.start();
    worker.join(limitMs);

    if (worker.isAlive()) {
        try { input.close(); } catch (Exception ignored) {}
        worker.interrupt();
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Copy timed out");
    }

    try { input.close(); } catch (Exception ignored) {}

    if (state[0] == 2) {
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Copy error: " + errors[0]);
    }

    if (new java.io.File(dir, fileName).length() == 0) {
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Copied file is empty");
    }
    copiedAt = System.currentTimeMillis();
} catch (Exception failure) {
    try {
        if (input != void && input != null) input.close();
    } catch (Exception ignored) {}
    if (writing) {
        try {
            new java.io.File(dirPath, fileName).delete();
        } catch (Exception ignored) {}
    }
    errorMessage = failure.getMessage();
    if (errorMessage == null) errorMessage = "" + failure;
    callCentral("erro", errorMessage);
    throw failure;
}

