import java.io.File;
import java.io.FileOutputStream;

String base = "/storage/emulated/0/Tasker/projects_task/projects/whats-connect-api/system/central-disparos-wca/";

String[] jsonFiles = {
    "history.json",
    "json-audios.json",
    "json-files.json",
    "json-images.json",
    "json-messages.json",
    "json-polls.json",
    "json-status.json",
    "json-videos.json",
    "campaigns.json"
};

for (int i = 0; i < jsonFiles.length; i++) {
    String p = base + jsonFiles[i];
    File f = new File(p);
    if (!f.exists()) {
        File parent = f.getParentFile();
        if (parent != null && !parent.exists()) parent.mkdirs();
        FileOutputStream fos = new FileOutputStream(f);
        try {
            fos.write("[]".getBytes("UTF-8"));
        } finally {
            try { fos.close(); } catch (Exception e) {}
        }
        tasker.log("Criado: " + p);
    }
}

String sendCachePath = base + "send-cache";
File sc = new File(sendCachePath);
if (!sc.exists()) {
    File parentSC = sc.getParentFile();
    if (parentSC != null && !parentSC.exists()) parentSC.mkdirs();
    FileOutputStream fosSC = new FileOutputStream(sc);
    try {
    } finally {
        try { fosSC.close(); } catch (Exception e) {}
    }
    tasker.log("Criado: " + sendCachePath);
}

return "Verificação concluída.";

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

final int MAX_WAIT_MS = 35000;
int waitMs = 1000;
String waitClass = "inactive_or_without_status";
String controlName = "none";
String enabledValue = "";
String timeValue = "";
String type = "";
boolean enabled = false;
double configuredSeconds = 0.0;
String waitError = "";

try {
    type = tasker.getVariable("type_message");
    if (type == null || type.trim().isEmpty()) {
        type = tasker.getVariable("type");
    }
    if (type == null) type = "";
    type = type.trim().toLowerCase();

    Set typingTypes = new HashSet(Arrays.asList(
        "text_message", "group_text_message", "mencao_text_message", "group_mencao_text_message",
        "image_message", "group_image_message", "status_image_message",
        "link_message", "link_message_group", "link_group_message",
        "document_message", "file_message", "group_file_message",
        "quote_message", "video_note_message", "list_response_message", "buttons_response_message"
    ));

    Set recordingTypes = new HashSet(Arrays.asList(
        "audio_message", "group_audio_message"
    ));

    Set videoTypes = new HashSet(Arrays.asList(
        "video_message", "group_video_message", "status_video_message"
    ));

    Set noStatusTypes = new HashSet(Arrays.asList(
        "avartar_contact_add_message", "avartar_contact_revoke_message", "change_avatar_message", 
        "change_name_group_message", "change_name_message", "change_photo_group_message", 
        "check_user_message", "contact_message_calendar", "create_group_message", "delete_message", 
        "delete_status_message", "delete_status_message_id", "disappearing_message", "end_call_message", 
        "get_avatar_group_message", "get_avatar_message", "group_delete_message", "group_interactive_buttons", 
        "group_interactive_buttons_list", "group_location_message", "group_mention_score", "group_poll_message", 
        "interactive_buttons", "interactive_buttons_list", "list_contact_message", "list_group_message", 
        "location_message", "live_location_message", "locked_group_message", "make_call", "manage_users_message", 
        "mark_group_message", "mark_message", "pin_conversation_message", "poll_message", "return_contact_message", 
        "status_message", "topic_group_message", "contact_message"
    ));

    if (recordingTypes.contains(type)) {
        controlName = "recording";
        enabledValue = tasker.getVariable("recording");
        timeValue = tasker.getVariable("recording_time");
    } else if (typingTypes.contains(type)) {
        controlName = "typing";
        enabledValue = tasker.getVariable("typing");
        timeValue = tasker.getVariable("typing_time");
    } else if (videoTypes.contains(type)) {
        controlName = "typing_video";
        enabledValue = tasker.getVariable("typing");
        timeValue = tasker.getVariable("typing_time");
    } else if (noStatusTypes.contains(type)) {
        controlName = "none";
        enabledValue = "false";
        timeValue = "0";
    } else {
        controlName = "unknown";
        enabledValue = "false";
        timeValue = "0";
    }

    if (enabledValue == null) {
        enabledValue = "";
        waitError += "Falha ao ler enabled. ";
    }
    if (timeValue == null) {
        timeValue = "";
        waitError += "Falha ao ler time. ";
    }

    enabledValue = enabledValue.trim().toLowerCase();
    timeValue = timeValue.trim().replace(',', '.');

    enabled = enabledValue.equals("true") || enabledValue.equals("1") || 
              enabledValue.equals("yes") || enabledValue.equals("on");

    try {
        configuredSeconds = Double.parseDouble(timeValue);
    } catch (Exception ignoredTime) {
        configuredSeconds = 0.0;
    }

    if (enabled && configuredSeconds >= 2.0) {
        waitMs = 0;
        waitClass = "covered_by_status_wait";
    } else if (enabled && configuredSeconds >= 1.0) {
        waitMs = 200;
        waitClass = "status_wait_complement";
    } else if (enabled) {
        waitMs = 1000;
        waitClass = "invalid_status_time";
    } else {
        waitMs = 1000;
        waitClass = "inactive_or_without_status";
    }
} catch (Exception calculationError) {
    waitMs = 1000;
    waitClass = "error_fallback";
    waitError += " Erro: " + String.valueOf(calculationError);
}

waitMs = Math.max(0, Math.min(waitMs, MAX_WAIT_MS));

try {
    tasker.setVariable("wait_ms", String.valueOf(waitMs));
    tasker.setVariable("wait_class", waitClass);
    tasker.setVariable("wait_type", type);
    tasker.setVariable("wait_control", controlName);
    tasker.setVariable("wait_control_enabled", String.valueOf(enabled));
    tasker.setVariable("wait_control_time", String.valueOf(configuredSeconds));
    tasker.setVariable("wait_error", waitError.trim());
} catch (Exception ignoredDiagnosticBefore) {
}

