function get(name) {
    try {
        var v = local(name);
        if (v === undefined || v === null) return "";
        return String(v);
    } catch (e) {
        return "";
    }
}

try {
    var number = get("number").trim();
    var lid = get("lid").trim().toLowerCase() === "true";
    var phone = number + (lid ? "@lid" : "@s.whatsapp.net");

    var rows = [];
    for (var i = 1; i <= 30; i++) {
        var raw = get("button" + i).trim().replace(/,\s*$/, "");
        if (!raw) continue;

        var defaultId = "row_" + (i < 10 ? "0" + i : i);
        var row = null;

        if (raw.charAt(0) === "{") {
            try {
                var obj = JSON.parse(raw);
                var t = String(obj.title || "").trim();
                if (t) {
                    row = { row_id: String(obj.row_id || defaultId), title: t };
                    var d = String(obj.footer || obj.description || "").trim();
                    if (d) row.description = d;
                }
            } catch (e) {
                row = null;
            }
        }

        if (!row) {
            var parts = raw.split("|");
            var rowTitle = parts[0].trim();
            if (!rowTitle) continue;
            row = { row_id: defaultId, title: rowTitle };
            var desc = parts.slice(1).join("|").trim();
            if (desc) row.description = desc;
        }

        rows.push(row);
    }

    var wantsPaginate = get("paginate").trim().toLowerCase() === "true";
    var usePaginate = wantsPaginate && rows.length > 10;
    if (!usePaginate) rows = rows.slice(0, 10);

    var data = { phone: phone };

    var title = get("title").trim();
    if (title) data.title = title;

    data.description = get("message_button");

    var footer = get("footer_button").trim();
    if (footer) data.footer = footer;

    data.button_text = get("page_header").trim() || "Ver opções";
    data.paginate = usePaginate;

    if (usePaginate) {
        data.page_size = 9;
        data.pagination_label = get("button_page").trim() || "Ver mais";
        data.forward_pagination = false;
    }

    var sectionTitle = get("page_title").trim() || "Opções";
    data.sections = [{ title: sectionTitle, rows: rows }];

    setLocal("list_json", JSON.stringify(data, null, 2));
    setLocal("list_error", "");
} catch (e) {
    setLocal("list_error", String(e));
    setLocal("list_json", "");
}

