canvas.drawCircle(165, 160, 85, circlePaint);

iconPaint = new Paint();
iconPaint.setColor(Color.BLACK);
iconPaint.setStyle(Paint.Style.FILL);
iconPaint.setAntiAlias(true);
canvas.save();
canvas.translate(165, 160);
canvas.rotate(45);
canvas.drawRect(-15, -15, 15, 15, iconPaint);
canvas.drawRect(-45, -45, -20, -20, iconPaint);
canvas.drawRect(20, 20, 45, 45, iconPaint);
canvas.drawRect(20, -45, 45, -20, iconPaint);
canvas.drawRect(-45, 20, -20, 45, iconPaint);
canvas.restore();

namePaint = new Paint();
namePaint.setColor(Color.WHITE);
namePaint.setTextSize(64);
namePaint.setTypeface(Typeface.DEFAULT_BOLD);
namePaint.setAntiAlias(true);

textX = 280;
maxNameWidth = width - textX - 50;

nameLine1 = "";
nameLine2 = "";
isSecondLine = false;

words = contact_name.split(" ");
for (int i = 0; i < words.length; i++) {
    word = words[i];
    if (isSecondLine) {
        if (nameLine2.length() == 0) {
            nameLine2 = word;
        } else {
            nameLine2 = nameLine2 + " " + word;
        }
    } else {
        if (nameLine1.length() == 0) {
            testLine = word;
        } else {
            testLine = nameLine1 + " " + word;
        }

        if (namePaint.measureText(testLine) <= maxNameWidth) {
            nameLine1 = testLine;
        } else {
            isSecondLine = true;
            nameLine2 = word;
        }
    }
}

line1Width = namePaint.measureText(nameLine1);
line2Width = namePaint.measureText(nameLine2);

if (line1Width > maxNameWidth || line2Width > maxNameWidth) {
    maxLineWidth = Math.max(line1Width, line2Width);
    newSize = (int)(64 * (maxNameWidth / maxLineWidth));
    namePaint.setTextSize(newSize);
}

if (nameLine2.length() > 0) {
    canvas.drawText(nameLine1, textX, 145, namePaint);
    canvas.drawText(nameLine2, textX, 215, namePaint);
    phoneY = 285;
} else {
