import org.json.JSONObject;
import org.json.JSONArray;
import org.json.JSONTokener;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

httpRequestBody = tasker.getVariable("http_request_body");

// ============================================================
// Protecao: o corpo recebido pode nao ser um objeto JSON valido
// (ex.: um texto solto como "instanceName"). Antes disso quebrava
// a tarefa inteira no new JSONObject(). Agora o conteudo e
// validado, registrado para diagnostico e a tarefa continua com
// os valores padrao vazios em vez de abortar.
// ============================================================
rawInput = (httpRequestBody == null) ? "" : httpRequestBody.trim();
parseErrorMsg = "";
data = null;

if (rawInput.length() == 0) {
    parseErrorMsg = "corpo da requisicao vazio";
} else if (rawInput.startsWith("{")) {
    try {
        data = new JSONObject(rawInput);
    } catch (Exception eParse) {
        parseErrorMsg = "JSON invalido: " + eParse.getMessage();
    }
} else {
    // Nao comeca com '{': pode ser um JSON duplo codificado (uma string
    // que contem um objeto). Tenta decodificar uma vez antes de desistir.
    try {
        unwrapped = new JSONTokener(rawInput).nextValue();
        if (unwrapped instanceof String) {
            inner = ((String) unwrapped).trim();
            if (inner.startsWith("{")) {
                data = new JSONObject(inner);
            }
        }
    } catch (Exception eUnwrap) {
        // ignora: tratado como corpo invalido abaixo
    }
    if (data == null) {
        parseErrorMsg = "corpo da requisicao nao e um objeto JSON (recebido: " + rawInput.substring(0, Math.min(200, rawInput.length())) + ")";
    }
}

if (data == null) {
    // Segue com objeto vazio: todas as variaveis de saida recebem o
    // valor padrao (vazio) e a tarefa nao e abortada.
    data = new JSONObject();
}

// Diagnostico: guarda exatamente o que chegou no webhook
tasker.setVariable("json_raw_input", rawInput.substring(0, Math.min(500, rawInput.length())));

try {

    // Campos principais do nível raiz
    if (data.has("recebido_em")) {
        tasker.setVariable("recebido_em", data.optString("recebido_em", ""));
    } else {
        tasker.setVariable("recebido_em", "");
    }

    if (data.has("origem")) {
        tasker.setVariable("origem", data.optString("origem", ""));
    } else {
        tasker.setVariable("origem", "");
    }

    if (data.has("metodo")) {
        tasker.setVariable("metodo", data.optString("metodo", ""));
    } else {
        tasker.setVariable("metodo", "");
    }

    if (data.has("url_original")) {
        tasker.setVariable("url_original", data.optString("url_original", ""));
    } else {
        tasker.setVariable("url_original", "");
    }

    if (data.has("porta_origem")) {
        tasker.setVariable("porta_origem", data.optString("porta_origem", ""));
    } else {
        tasker.setVariable("porta_origem", "");
    }

    if (data.has("porta_destino")) {
        tasker.setVariable("porta_destino", data.optString("porta_destino", ""));
    } else {
        tasker.setVariable("porta_destino", "");
    }

    // Processa o body principal
    if (data.has("body")) {
        body = data.optJSONObject("body");
        if (body != null) {

            // DeviceID
            if (body.has("DeviceID")) {
                String rawDeviceId = body.optString("DeviceID", "");
                String cleanDeviceId = rawDeviceId;
                if (rawDeviceId.contains("@")) {
                    cleanDeviceId = rawDeviceId.substring(0, rawDeviceId.indexOf("@"));
                }
                tasker.setVariable("device_id", cleanDeviceId);
                tasker.setVariable("phone", cleanDeviceId);
            } else {
                tasker.setVariable("device_id", "");
                tasker.setVariable("phone", "");
            }

            // Event
            event = body.optString("Event", "");
            if (body.has("Event")) {
                tasker.setVariable("event", event);
            } else {
                tasker.setVariable("event", "");
            }

            // Timestamp do body
            if (body.has("Timestamp")) {
                tasker.setVariable("timestamp_body", body.optString("Timestamp", ""));
            } else {
                tasker.setVariable("timestamp_body", "");
            }

            // Processa o payload
            if (body.has("Payload")) {
                p = body.optJSONObject("Payload");
                if (p != null) {

                    // ChatID
                    if (p.has("ChatID")) {
                        String chatIdValue = p.optString("ChatID", "");
                        tasker.setVariable("chat_id", chatIdValue);

                        String recipientNumberRaw = chatIdValue;
                        if (recipientNumberRaw.endsWith("@s.whatsapp.net")) {
                            recipientNumberRaw = recipientNumberRaw.replace("@s.whatsapp.net", "");
                        } else if (recipientNumberRaw.endsWith("@g.us")) {
                            recipientNumberRaw = recipientNumberRaw.replace("@g.us", "");
                        }
                        tasker.setVariable("recipient_number", recipientNumberRaw);
                    } else {
                        tasker.setVariable("chat_id", "");
                        tasker.setVariable("recipient_number", "");
                    }

                    // ChatLid / FromLid
                    if (p.has("ChatLid")) {
                        tasker.setVariable("from_lid", p.optString("ChatLid", ""));
                    } else if (p.has("FromLid")) {
                        tasker.setVariable("from_lid", p.optString("FromLid", ""));
                    } else {
                        tasker.setVariable("from_lid", "");
                    }

                    // From
                    if (p.has("From")) {
                        String fromRaw = p.optString("From", "");
                        String senderNumberRaw = fromRaw;
                        if (senderNumberRaw.endsWith("@s.whatsapp.net")) {
                            senderNumberRaw = senderNumberRaw.replace("@s.whatsapp.net", "");
                        } else if (senderNumberRaw.endsWith("@g.us")) {
                            senderNumberRaw = senderNumberRaw.replace("@g.us", "");
                        }
                        tasker.setVariable("sender_number", senderNumberRaw);
                    } else {
                        tasker.setVariable("sender_number", "");
                    }

                    // FromName
                    if (p.has("FromName")) {
                        tasker.setVariable("sender_name", p.optString("FromName", ""));
                    } else {
                        tasker.setVariable("sender_name", "");
                    }

                    // IsFromMe
                    if (p.has("IsFromMe")) {
                        tasker.setVariable("is_from_me", String.valueOf(p.optBoolean("IsFromMe")));
                    } else {
                        tasker.setVariable("is_from_me", "false");
                    }

                    // IsGroup
                    if (p.has("IsGroup")) {
                        boolean isGroupBoolean = p.optBoolean("IsGroup");
                        tasker.setVariable("is_group", String.valueOf(isGroupBoolean));

                        if (isGroupBoolean) {
                            String groupJidValue = p.optString("ChatID", "");
                            if (groupJidValue.endsWith("@g.us")) {
                                groupJidValue = groupJidValue.replace("@g.us", "");
                            }
                            tasker.setVariable("group_jid", groupJidValue);
                        } else {
                            tasker.setVariable("group_jid", "");
                        }
                    } else {
                        tasker.setVariable("is_group", "false");
                        tasker.setVariable("group_jid", "");
                    }

                    // GroupName (para grupos)
                    if (p.has("GroupName")) {
                        tasker.setVariable("group_name", p.optString("GroupName", ""));
                    } else {
                        tasker.setVariable("group_name", "");
                    }

                    // ID / IDs
                    if (p.has("IDs")) {
                        ids = p.optJSONArray("IDs");
                        if (ids != null && ids.length() > 0) {
                            tasker.setVariable("ids_json", ids.toString());
                            tasker.setVariable("ids_count", String.valueOf(ids.length()));
                            tasker.setVariable("message_id", ids.optString(0, ""));
                        } else {
                            tasker.setVariable("ids_json", "");
                            tasker.setVariable("ids_count", "0");
                            tasker.setVariable("message_id", "");
                        }
                    } else if (p.has("ID")) {
                        tasker.setVariable("message_id", p.optString("ID", ""));
                        tasker.setVariable("ids_json", "");
                        tasker.setVariable("ids_count", "0");
                    } else {
                        tasker.setVariable("message_id", "");
                        tasker.setVariable("ids_json", "");
                        tasker.setVariable("ids_count", "0");
                    }

                    // Timestamp do payload
                    if (p.has("Timestamp")) {
                        tasker.setVariable("timestamp_payload", p.optString("Timestamp", ""));
                    } else {
                        tasker.setVariable("timestamp_payload", "");
                    }

                    // Body / Message (texto)
                    if (p.has("Body")) {
                        tasker.setVariable("message_text", p.optString("Body", ""));
                    } else {
                        tasker.setVariable("message_text", "");
                    }

                    // ========================================
                    // TYPE MESSAGE
                    // ========================================
                    String typeMessage = "";

                    // Verifica se é evento de mensagem revogada (apagada)
                    if (event.equals("message.revoked")) {
                        tasker.setVariable("type_message", "message_revoked");

                        if (p.has("RevokedMessageID")) {
                            tasker.setVariable("revoked_message_id", p.optString("RevokedMessageID", ""));
                        } else {
                            tasker.setVariable("revoked_message_id", "");
                        }

                        if (p.has("RevokedChat")) {
                            tasker.setVariable("revoked_chat", p.optString("RevokedChat", ""));
                        } else {
                            tasker.setVariable("revoked_chat", "");
                        }

                        if (p.has("RevokedFromMe")) {
                            tasker.setVariable("revoked_from_me", String.valueOf(p.optBoolean("RevokedFromMe")));
                        } else {
                            tasker.setVariable("revoked_from_me", "false");
                        }
                    } else if (p.has("Type")) {
                        typeMessage = p.optString("Type", "");

                        if (typeMessage.equals("Message")) {
                            tasker.setVariable("type_message", "text_message");
                        } else if (typeMessage.equals("VideoMessage")) {
                            tasker.setVariable("type_message", "video_message");
                        } else if (typeMessage.equals("ImageMessage")) {
                            tasker.setVariable("type_message", "image_message");
                        } else if (typeMessage.equals("AudioMessage")) {
                            tasker.setVariable("type_message", "audio_message");
                        } else if (typeMessage.equals("DocumentMessage")) {
                            tasker.setVariable("type_message", "document_message");
                        } else if (typeMessage.equals("LinkMessage")) {
                            tasker.setVariable("type_message", "link_message");
                        } else if (typeMessage.equals("LocationMessage")) {
                            tasker.setVariable("type_message", "location_message");
                        } else if (typeMessage.equals("LiveLocationMessage")) {
                            tasker.setVariable("type_message", "live_location_message");
                        } else if (typeMessage.equals("VideoNoteMessage")) {
                            tasker.setVariable("type_message", "video_note_message");
                        } else if (typeMessage.equals("ContactMessage")) {
                            tasker.setVariable("type_message", "contact_message");
                        } else if (typeMessage.equals("ReceiptMessage")) {
                            tasker.setVariable("type_message", "receipt_message");
                        } else if (typeMessage.equals("ChatPresenceMessage")) {
                            tasker.setVariable("type_message", "presence_message");
                        } else if (typeMessage.equals("PollMessage")) {
                            tasker.setVariable("type_message", "poll_message");
                        } else if (typeMessage.equals("PollResponseMessage")) {
                            tasker.setVariable("type_message", "poll_response_message");
                        } else if (typeMessage.equals("StatusResponseMessage")) {
                            tasker.setVariable("type_message", "status_response_message");
                        } else if (typeMessage.equals("QuoteMessage")) {
                            tasker.setVariable("type_message", "quote_message");
                        } else if (typeMessage.equals("CallOfferMessage") || typeMessage.equals("VideoCallOfferMessage") || typeMessage.equals("AudioCallOfferMessage")) {
                            tasker.setVariable("type_message", "call_offer");
                        } else if (typeMessage.equals("CallTerminateMessage")) {
                            tasker.setVariable("type_message", "call_terminate");
                        } else {
                            tasker.setVariable("type_message", typeMessage.toLowerCase() + "_message");
                        }
                    } else {
                        tasker.setVariable("type_message", "");
                    }

                    // ========================================
                    // STATUS RESPONSE MESSAGE (Resposta a Status)
                    // ========================================
                    if (p.has("QuotedStatusID")) {
                        tasker.setVariable("quoted_status_id", p.optString("QuotedStatusID", ""));
                    } else {
                        tasker.setVariable("quoted_status_id", "");
                    }

                    if (p.has("QuotedStatusCaption")) {
                        tasker.setVariable("quoted_status_caption", p.optString("QuotedStatusCaption", ""));
                    } else {
                        tasker.setVariable("quoted_status_caption", "");
                    }

                    if (p.has("QuotedStatusSender")) {
                        tasker.setVariable("quoted_status_sender", p.optString("QuotedStatusSender", ""));
                    } else {
                        tasker.setVariable("quoted_status_sender", "");
                    }

                    if (p.has("QuotedStatusType")) {
                        tasker.setVariable("quoted_status_type", p.optString("QuotedStatusType", ""));
                    } else {
                        tasker.setVariable("quoted_status_type", "");
                    }

                    // ========================================
                    // QUOTE MESSAGE (Mensagem com Citação)
                    // ========================================
                    if (p.has("QuotedBody")) {
                        tasker.setVariable("quoted_body", p.optString("QuotedBody", ""));
                    } else {
                        tasker.setVariable("quoted_body", "");
                    }

                    if (p.has("RepliedToID")) {
                        tasker.setVariable("replied_to_id", p.optString("RepliedToID", ""));
                    } else {
                        tasker.setVariable("replied_to_id", "");
                    }

                    // ========================================
                    // POLL MESSAGE
                    // ========================================
                    if (p.has("Poll")) {
                        JSONObject pollObj = p.optJSONObject("Poll");
                        if (pollObj != null) {
                            if (pollObj.has("Question")) {
                                tasker.setVariable("poll_question", pollObj.optString("Question", ""));
                            } else {
                                tasker.setVariable("poll_question", "");
                            }

                            if (pollObj.has("Options")) {
                                JSONArray pollOptions = pollObj.optJSONArray("Options");
                                if (pollOptions != null) {
                                    tasker.setVariable("poll_options_json", pollOptions.toString());
                                    tasker.setVariable("poll_options_count", String.valueOf(pollOptions.length()));
                                } else {
                                    tasker.setVariable("poll_options_json", "");
                                    tasker.setVariable("poll_options_count", "0");
                                }
                            } else {
                                tasker.setVariable("poll_options_json", "");
                                tasker.setVariable("poll_options_count", "0");
                            }

                            if (pollObj.has("EncKey")) {
                                tasker.setVariable("poll_enc_key", pollObj.optString("EncKey", ""));
                            } else {
                                tasker.setVariable("poll_enc_key", "");
                            }

                            tasker.setVariable("poll_json", pollObj.toString());
                        } else {
                            tasker.setVariable("poll_question", "");
                            tasker.setVariable("poll_options_json", "");
                            tasker.setVariable("poll_options_count", "0");
                            tasker.setVariable("poll_enc_key", "");
                            tasker.setVariable("poll_json", "");
                        }
                    } else {
                        tasker.setVariable("poll_question", "");
                        tasker.setVariable("poll_options_json", "");
                        tasker.setVariable("poll_options_count", "0");
                        tasker.setVariable("poll_enc_key", "");
                        tasker.setVariable("poll_json", "");
                    }

                    // ========================================
                    // POLL RESPONSE MESSAGE
                    // ========================================
                    if (p.has("PollQuestion")) {
                        tasker.setVariable("poll_response_question", p.optString("PollQuestion", ""));
                    } else {
                        tasker.setVariable("poll_response_question", "");
                    }

                    if (p.has("PollOptions")) {
                        JSONArray pollResponseOptions = p.optJSONArray("PollOptions");
                        if (pollResponseOptions != null) {
                            tasker.setVariable("poll_response_options_json", pollResponseOptions.toString());
                            tasker.setVariable("poll_response_options_count", String.valueOf(pollResponseOptions.length()));
                        } else {
                            tasker.setVariable("poll_response_options_json", "");
                            tasker.setVariable("poll_response_options_count", "0");
                        }
                    } else {
                        tasker.setVariable("poll_response_options_json", "");
                        tasker.setVariable("poll_response_options_count", "0");
                    }

                    if (p.has("PollVotes")) {
                        JSONArray pollVotes = p.optJSONArray("PollVotes");
                        if (pollVotes != null && pollVotes.length() > 0) {
                            tasker.setVariable("poll_response_vote", pollVotes.optString(0, ""));
                            tasker.setVariable("poll_response_votes_json", pollVotes.toString());
                            tasker.setVariable("poll_response_votes_count", String.valueOf(pollVotes.length()));
                        } else {
                            tasker.setVariable("poll_response_vote", "");
                            tasker.setVariable("poll_response_votes_json", "");
                            tasker.setVariable("poll_response_votes_count", "0");
                        }
                    } else {
                        tasker.setVariable("poll_response_vote", "");
                        tasker.setVariable("poll_response_votes_json", "");
                        tasker.setVariable("poll_response_votes_count", "0");
                    }

                    if (p.has("OriginalMessageID")) {
                        tasker.setVariable("poll_original_message_id", p.optString("OriginalMessageID", ""));
                    } else {
                        tasker.setVariable("poll_original_message_id", "");
                    }

                    // ========================================
                    // BOTOES E LISTAS INTERATIVAS (RESPOSTA DO CLIENTE)
                    // ========================================
                    // A API envia um objeto unificado "InteractiveReply" tanto para
                    // clique em botao quanto para selecao em lista. Os objetos
                    // "ListReply" e "ButtonsReply" trazem o detalhe por formato.
                    //
                    // O campo mais importante e' interactive_selected_id: ele devolve
                    // exatamente o "id" (botao) ou "row_id" (lista) definido no envio.

                    // Limpa todas as variaveis antes de preencher
                    tasker.setVariable("buttons_sent", "false");
                    tasker.setVariable("buttons_sent_json", "");
                    tasker.setVariable("buttons_sent_count", "0");
                    tasker.setVariable("buttons_sent_titles", "");
                    tasker.setVariable("buttons_sent_ids", "");
                    tasker.setVariable("list_sent", "false");
                    tasker.setVariable("list_sent_json", "");
                    tasker.setVariable("list_sent_rows_count", "0");
                    tasker.setVariable("list_sent_titles", "");
                    tasker.setVariable("list_sent_ids", "");
                    tasker.setVariable("interactive_reply", "false");
                    tasker.setVariable("interactive_type", "");
                    tasker.setVariable("interactive_selected_id", "");
                    tasker.setVariable("interactive_selected_text", "");
                    tasker.setVariable("interactive_body", "");
                    tasker.setVariable("interactive_name", "");
                    tasker.setVariable("interactive_params_json", "");
                    tasker.setVariable("interactive_json", "");
                    tasker.setVariable("list_selected_id", "");
                    tasker.setVariable("list_selected_title", "");
                    tasker.setVariable("list_selected_description", "");
                    tasker.setVariable("buttons_selected_id", "");
                    tasker.setVariable("buttons_selected_text", "");
                    tasker.setVariable("is_pagination", "false");
                    tasker.setVariable("forward_pagination", "false");
                    tasker.setVariable("pagination_page", "");
                    tasker.setVariable("pagination_total_pages", "");
                    tasker.setVariable("pagination_total_rows", "");
                    tasker.setVariable("pagination_message_id", "");
                    tasker.setVariable("pagination_rows_count", "");
                    tasker.setVariable("pagination_has_more", "");
                    tasker.setVariable("pagination_titles", "");
                    tasker.setVariable("pagination_ids", "");
                    tasker.setVariable("pagination_json", "");

                    // --- ButtonsSent: botoes que VOCE enviou (eco do envio) ---
                    if (p.has("ButtonsSent")) {
                        JSONObject sentObj = p.optJSONObject("ButtonsSent");
                        if (sentObj != null) {
                            tasker.setVariable("buttons_sent", "true");
                            tasker.setVariable("buttons_sent_json", sentObj.toString());
                            tasker.setVariable("buttons_sent_count", String.valueOf(sentObj.optInt("ButtonsCount", 0)));

                            JSONArray sentButtons = sentObj.optJSONArray("Buttons");
                            if (sentButtons != null) {
                                StringBuilder titles = new StringBuilder();
                                StringBuilder btnIds = new StringBuilder();
                                for (int i = 0; i < sentButtons.length(); i++) {
                                    JSONObject b = sentButtons.optJSONObject(i);
                                    if (b == null) continue;
                                    if (titles.length() > 0) titles.append(",");
                                    if (btnIds.length() > 0) btnIds.append(",");
                                    titles.append(b.optString("Title", ""));
                                    btnIds.append(b.optString("ID", ""));
                                }
                                tasker.setVariable("buttons_sent_titles", titles.toString());
                                tasker.setVariable("buttons_sent_ids", btnIds.toString());
                            }
                        }
                    }

                    // --- ListSent: lista que VOCE enviou (eco do envio) ---
                    if (p.has("ListSent")) {
                        JSONObject sentListObj = p.optJSONObject("ListSent");
                        if (sentListObj != null) {
                            tasker.setVariable("list_sent", "true");
                            tasker.setVariable("list_sent_json", sentListObj.toString());
                            tasker.setVariable("list_sent_rows_count", String.valueOf(sentListObj.optInt("RowsCount", 0)));

                            JSONArray sentSections = sentListObj.optJSONArray("Sections");
                            if (sentSections != null) {
                                StringBuilder rowTitles = new StringBuilder();
                                StringBuilder rowIds = new StringBuilder();
                                for (int i = 0; i < sentSections.length(); i++) {
                                    JSONObject sec = sentSections.optJSONObject(i);
                                    if (sec == null) continue;
                                    JSONArray secRows = sec.optJSONArray("Rows");
                                    if (secRows == null) continue;
                                    for (int j = 0; j < secRows.length(); j++) {
                                        JSONObject r = secRows.optJSONObject(j);
                                        if (r == null) continue;
                                        if (rowTitles.length() > 0) rowTitles.append(",");
                                        if (rowIds.length() > 0) rowIds.append(",");
                                        rowTitles.append(r.optString("Title", ""));
                                        rowIds.append(r.optString("RowID", ""));
                                    }
                                }
                                tasker.setVariable("list_sent_titles", rowTitles.toString());
                                tasker.setVariable("list_sent_ids", rowIds.toString());
                            }
                        }
                    }

                    // --- InteractiveReply (unificado: botoes e listas) ---
                    if (p.has("InteractiveReply")) {
                        JSONObject interactiveObj = p.optJSONObject("InteractiveReply");
                        if (interactiveObj != null) {
                            tasker.setVariable("interactive_reply", "true");
                            tasker.setVariable("interactive_json", interactiveObj.toString());
                            tasker.setVariable("interactive_type", interactiveObj.optString("Type", ""));
                            tasker.setVariable("interactive_selected_id", interactiveObj.optString("SelectedID", ""));
                            tasker.setVariable("interactive_selected_text", interactiveObj.optString("SelectedText", ""));
                            tasker.setVariable("interactive_body", interactiveObj.optString("Body", ""));
                            tasker.setVariable("interactive_name", interactiveObj.optString("Name", ""));
                            tasker.setVariable("interactive_params_json", interactiveObj.optString("ParamsJSON", ""));

                            // Em lista o texto visivel chega em "Title"
                            if (interactiveObj.optString("SelectedText", "").equals("")
                                    && interactiveObj.has("Title")) {
                                tasker.setVariable("interactive_selected_text", interactiveObj.optString("Title", ""));
                            }
                        }
                    }

                    // --- ListReply (apenas selecao em lista) ---
                    if (p.has("ListReply")) {
                        JSONObject listReplyObj = p.optJSONObject("ListReply");
                        if (listReplyObj != null) {
                            tasker.setVariable("interactive_reply", "true");
                            tasker.setVariable("list_selected_id", listReplyObj.optString("SelectedID", ""));
                            tasker.setVariable("list_selected_title", listReplyObj.optString("Title", ""));
                            tasker.setVariable("list_selected_description", listReplyObj.optString("Description", ""));

                            if (tasker.getVariable("interactive_type").equals("")) {
                                tasker.setVariable("interactive_type", listReplyObj.optString("Type", "list"));
                            }
                            if (tasker.getVariable("interactive_selected_id").equals("")) {
                                tasker.setVariable("interactive_selected_id", listReplyObj.optString("SelectedID", ""));
                            }
                            if (tasker.getVariable("interactive_selected_text").equals("")) {
                                tasker.setVariable("interactive_selected_text", listReplyObj.optString("Title", ""));
                            }
                        }
                    }

                    // --- ButtonsReply (botoes de formato legado) ---
                    if (p.has("ButtonsReply")) {
                        JSONObject buttonsReplyObj = p.optJSONObject("ButtonsReply");
                        if (buttonsReplyObj != null) {
                            tasker.setVariable("interactive_reply", "true");
                            tasker.setVariable("buttons_selected_id", buttonsReplyObj.optString("SelectedID", ""));
                            tasker.setVariable("buttons_selected_text", buttonsReplyObj.optString("SelectedText", ""));

                            if (tasker.getVariable("interactive_type").equals("")) {
                                tasker.setVariable("interactive_type", buttonsReplyObj.optString("Type", "buttons_legacy"));
                            }
                            if (tasker.getVariable("interactive_selected_id").equals("")) {
                                tasker.setVariable("interactive_selected_id", buttonsReplyObj.optString("SelectedID", ""));
                            }
                            if (tasker.getVariable("interactive_selected_text").equals("")) {
                                tasker.setVariable("interactive_selected_text", buttonsReplyObj.optString("SelectedText", ""));
                            }
                        }
                    }

                    // --- Marca clique em "Ver mais" (navegacao, nao escolha) ---
                    // Presente na resposta de navegacao. Use is_pagination para
                    // ignorar a navegacao e tratar so as escolhas reais. O valor de
                    // forward_pagination exibe como a lista foi configurada no envio.
                    if (p.has("InteractiveReply")) {
                        JSONObject irObj = p.optJSONObject("InteractiveReply");
                        if (irObj != null) {
                            if (irObj.has("ForwardPagination")) {
                                tasker.setVariable("forward_pagination", String.valueOf(irObj.optBoolean("ForwardPagination", false)));
                            }
                            if (irObj.has("IsPagination")) {
                                boolean isPag = irObj.optBoolean("IsPagination", false);
                                tasker.setVariable("is_pagination", String.valueOf(isPag));
                                if (isPag) {
                                    tasker.setVariable("pagination_page", String.valueOf(irObj.optInt("Page", 0)));
                                    tasker.setVariable("pagination_total_pages", String.valueOf(irObj.optInt("TotalPages", 0)));
                                    tasker.setVariable("pagination_total_rows", String.valueOf(irObj.optInt("TotalRows", 0)));
                                }
                            }
                        }
                    }

                    // --- PaginationSent: conteudo da pagina que foi aberta ---
                    if (p.has("PaginationSent")) {
                        JSONObject pagObj = p.optJSONObject("PaginationSent");
                        if (pagObj != null) {
                            tasker.setVariable("is_pagination", "true");
                            if (pagObj.has("ForwardPagination")) {
                                tasker.setVariable("forward_pagination", String.valueOf(pagObj.optBoolean("ForwardPagination", false)));
                            }
                            tasker.setVariable("pagination_json", pagObj.toString());
                            tasker.setVariable("pagination_message_id", pagObj.optString("MessageID", ""));
                            tasker.setVariable("pagination_page", String.valueOf(pagObj.optInt("Page", 0)));
                            tasker.setVariable("pagination_total_pages", String.valueOf(pagObj.optInt("TotalPages", 0)));
                            tasker.setVariable("pagination_total_rows", String.valueOf(pagObj.optInt("TotalRows", 0)));
                            tasker.setVariable("pagination_rows_count", String.valueOf(pagObj.optInt("RowsCount", 0)));
                            tasker.setVariable("pagination_has_more", String.valueOf(pagObj.optBoolean("HasMore", false)));

                            JSONArray pagRows = pagObj.optJSONArray("Rows");
                            if (pagRows != null) {
                                StringBuilder pTitles = new StringBuilder();
                                StringBuilder pIds = new StringBuilder();
                                for (int i = 0; i < pagRows.length(); i++) {
                                    JSONObject r = pagRows.optJSONObject(i);
                                    if (r == null) continue;
                                    if (pTitles.length() > 0) pTitles.append(",");
                                    if (pIds.length() > 0) pIds.append(",");
                                    pTitles.append(r.optString("Title", ""));
                                    pIds.append(r.optString("RowID", ""));
                                }
                                tasker.setVariable("pagination_titles", pTitles.toString());
                                tasker.setVariable("pagination_ids", pIds.toString());
                            }
                        }
                    }

                    // Ajusta o type_message quando for resposta interativa,
                    // facilitando o filtro no perfil do Tasker.
                    if (tasker.getVariable("interactive_reply").equals("true")) {
                        String interactiveType = tasker.getVariable("interactive_type");
                        if (interactiveType.equals("list")) {
                            tasker.setVariable("type_message", "list_response_message");
                        } else {
                            tasker.setVariable("type_message", "buttons_response_message");
                        }
                    }

                    // ========================================
                    // LINK MESSAGE
                    // ========================================
                    if (p.has("LinkTitle")) {
                        tasker.setVariable("link_title", p.optString("LinkTitle", ""));
                    } else {
                        tasker.setVariable("link_title", "");
                    }

                    if (p.has("LinkDescription")) {
                        tasker.setVariable("link_description", p.optString("LinkDescription", ""));
                    } else {
                        tasker.setVariable("link_description", "");
                    }

                    if (p.has("LinkThumbnailBase64")) {
                        tasker.setVariable("thumbnail_base64", p.optString("LinkThumbnailBase64", ""));
                    } else {
                        tasker.setVariable("thumbnail_base64", "");
                    }

                    if (p.has("Link_URL")) {
                        tasker.setVariable("link_url", p.optString("Link_URL", ""));
                    } else if (p.has("Body") && p.optString("Body", "").startsWith("http")) {
                        tasker.setVariable("link_url", p.optString("Body", ""));
                    } else {
                        tasker.setVariable("link_url", "");
                    }

                    // Extension
                    if (p.has("Extension")) {
                        tasker.setVariable("extension", p.optString("Extension", ""));
                    } else {
                        tasker.setVariable("extension", "");
                    }

                    // FileSizeKB
                    if (p.has("FileSizeKB")) {
                        tasker.setVariable("file_size_kb", String.valueOf(p.optDouble("FileSizeKB")));
                    } else {
                        tasker.setVariable("file_size_kb", "");
                    }

                    // Video
                    if (p.has("Video")) {
                        Object videoObj = p.opt("Video");
                        if (videoObj instanceof JSONObject) {
                            JSONObject videoJson = (JSONObject) videoObj;
                            tasker.setVariable("video_path", videoJson.optString("Path", ""));
                            tasker.setVariable("caption_video", videoJson.optString("Caption", ""));
                        } else {
                            tasker.setVariable("video_path", p.optString("Video", ""));
                            tasker.setVariable("caption_video", "");
                        }
                    } else {
                        tasker.setVariable("video_path", "");
                        tasker.setVariable("caption_video", "");
                    }

                    // VideoNote
                    if (p.has("VideoNote")) {
                        tasker.setVariable("video_note_path", p.optString("VideoNote", ""));
                        tasker.setVariable("caption_video_note", "");
                    } else {
                        tasker.setVariable("video_note_path", "");
                        tasker.setVariable("caption_video_note", "");
                    }

                    // Image
                    if (p.has("Image")) {
                        Object imageObj = p.opt("Image");
                        if (imageObj instanceof JSONObject) {
                            JSONObject imageJson = (JSONObject) imageObj;
                            tasker.setVariable("image_path", imageJson.optString("Path", ""));
                            tasker.setVariable("caption_image", imageJson.optString("Caption", ""));
                        } else {
                            tasker.setVariable("image_path", p.optString("Image", ""));
                            tasker.setVariable("caption_image", "");
                        }
                    } else {
                        tasker.setVariable("image_path", "");
                        tasker.setVariable("caption_image", "");
                    }

                    // Document
                    if (p.has("Document")) {
                        tasker.setVariable("document_path", p.optString("Document", ""));
                        tasker.setVariable("caption_document", "");
                    } else {
                        tasker.setVariable("document_path", "");
                        tasker.setVariable("caption_document", "");
                    }

                    // Audio
                    if (p.has("Audio")) {
                        tasker.setVariable("audio_path", p.optString("Audio", ""));
                        tasker.setVariable("caption_audio", "");
                    } else {
                        tasker.setVariable("audio_path", "");
                        tasker.setVariable("caption_audio", "");
                    }

                    // ========================================
                    // LOCATION
                    // ========================================
                    tasker.setVariable("location_latitude", "");
                    tasker.setVariable("location_longitude", "");

                    if (p.has("Latitude") && p.has("Longitude")) {
                        tasker.setVariable("location_latitude", String.valueOf(p.optDouble("Latitude")));
                        tasker.setVariable("location_longitude", String.valueOf(p.optDouble("Longitude")));
                    } else if (p.has("Location")) {
                        JSONObject locationObj = p.optJSONObject("Location");
                        if (locationObj != null) {
                            if (locationObj.has("degreesLatitude") && locationObj.has("degreesLongitude")) {
                                tasker.setVariable("location_latitude", String.valueOf(locationObj.optDouble("degreesLatitude", 0.0)));
                                tasker.setVariable("location_longitude", String.valueOf(locationObj.optDouble("degreesLongitude", 0.0)));
                            }
                            if (locationObj.has("JPEGThumbnail")) {
                                tasker.setVariable("thumbnail_base64", locationObj.optString("JPEGThumbnail", ""));
                            }
                        }
                    } else if (p.has("LiveLocation")) {
                        JSONObject liveLocationObj = p.optJSONObject("LiveLocation");
                        if (liveLocationObj != null) {
                            if (liveLocationObj.has("degreesLatitude") && liveLocationObj.has("degreesLongitude")) {
                                tasker.setVariable("location_latitude", String.valueOf(liveLocationObj.optDouble("degreesLatitude", 0.0)));
                                tasker.setVariable("location_longitude", String.valueOf(liveLocationObj.optDouble("degreesLongitude", 0.0)));
                            }
                            if (liveLocationObj.has("sequenceNumber")) {
                                tasker.setVariable("live_location_sequence_number", String.valueOf(liveLocationObj.optLong("sequenceNumber", 0)));
                            } else {
                                tasker.setVariable("live_location_sequence_number", "");
                            }
                            if (liveLocationObj.has("JPEGThumbnail")) {
                                tasker.setVariable("thumbnail_base64", liveLocationObj.optString("JPEGThumbnail", ""));
                            }
                        }
                    }

                    // Contact
                    if (p.has("ContactsArray")) {
                        JSONArray contactsArray = p.optJSONArray("ContactsArray");
                        if (contactsArray != null && contactsArray.length() > 0) {
                            tasker.setVariable("contacts_json", contactsArray.toString());
                            tasker.setVariable("contacts_count", String.valueOf(contactsArray.length()));
                        } else {
                            tasker.setVariable("contacts_json", "");
                            tasker.setVariable("contacts_count", "0");
                        }
                    } else {
                        tasker.setVariable("contacts_json", "");
                        tasker.setVariable("contacts_count", "0");
                    }

                    if (p.has("Contact")) {
                        JSONObject contactObj = p.optJSONObject("Contact");
                        if (contactObj != null) {
                            tasker.setVariable("contact_display_name", contactObj.optString("DisplayName", ""));
                            tasker.setVariable("contact_vcard", contactObj.optString("VCard", ""));
                        } else {
                            tasker.setVariable("contact_display_name", "");
                            tasker.setVariable("contact_vcard", "");
                        }
                    } else {
                        tasker.setVariable("contact_display_name", "");
                        tasker.setVariable("contact_vcard", "");
                    }

                    // Receipt
                    if (p.has("ReceiptType")) {
                        String receiptType = p.optString("ReceiptType", "");
                        tasker.setVariable("receipt_type", receiptType);
                        tasker.setVariable("is_receipt", "true");

                        if (receiptType.equals("delivered")) {
                            tasker.setVariable("is_delivered", "true");
                            tasker.setVariable("is_read", "false");
                        } else if (receiptType.equals("read")) {
                            tasker.setVariable("is_delivered", "false");
                            tasker.setVariable("is_read", "true");
                        } else {
                            tasker.setVariable("is_delivered", "false");
                            tasker.setVariable("is_read", "false");
                        }
                    } else {
                        tasker.setVariable("receipt_type", "");
                        tasker.setVariable("is_receipt", "false");
                        tasker.setVariable("is_delivered", "false");
                        tasker.setVariable("is_read", "false");
                    }

                    if (p.has("ReceiptTypeDescription")) {
                        tasker.setVariable("receipt_type_description", p.optString("ReceiptTypeDescription", ""));
                    } else {
                        tasker.setVariable("receipt_type_description", "");
                    }

                    // Presence
                    if (p.has("State")) {
                        tasker.setVariable("state", p.optString("State", ""));
                    } else {
                        tasker.setVariable("state", "");
                    }

                    if (p.has("Media")) {
                        tasker.setVariable("media_type", p.optString("Media", ""));
                    } else {
                        tasker.setVariable("media_type", "");
                    }

                    // Context Info
                    if (p.has("contextInfo")) {
                        JSONObject contextInfo = p.optJSONObject("contextInfo");
                        if (contextInfo != null) {
                            tasker.setVariable("context_info", contextInfo.toString());
                            if (contextInfo.has("expiration")) {
                                tasker.setVariable("expiration", String.valueOf(contextInfo.optLong("expiration")));
                            }
                            if (contextInfo.has("ephemeralSettingTimestamp")) {
                                tasker.setVariable("ephemeral_timestamp", String.valueOf(contextInfo.optLong("ephemeralSettingTimestamp")));
                            }
                        } else {
                            tasker.setVariable("context_info", "");
                            tasker.setVariable("expiration", "");
                            tasker.setVariable("ephemeral_timestamp", "");
                        }
                    } else {
                        tasker.setVariable("context_info", "");
                        tasker.setVariable("expiration", "");
                        tasker.setVariable("ephemeral_timestamp", "");
                    }
                }
            }

            // ========================================
            // CALL EVENTS
            // ========================================
            if (event.equals("call.offer") || event.equals("call.terminate")) {
                if (body.has("Payload")) {
                    callPayload = body.optJSONObject("Payload");
                    if (callPayload != null) {
                        if (callPayload.has("CallID")) tasker.setVariable("call_id", callPayload.optString("CallID", ""));
                        else tasker.setVariable("call_id", "");

                        if (callPayload.has("CallStatus")) tasker.setVariable("call_status", callPayload.optString("CallStatus", ""));
                        else tasker.setVariable("call_status", "");

                        if (callPayload.has("CallType")) tasker.setVariable("call_type", callPayload.optString("CallType", ""));
                        else tasker.setVariable("call_type", "");

                        if (callPayload.has("From")) {
                            String callFrom = callPayload.optString("From", "");
                            if (callFrom.contains("@")) {
                                callFrom = callFrom.substring(0, callFrom.indexOf("@"));
                            }
                            tasker.setVariable("call_sender_number", callFrom);
                        } else {
                            tasker.setVariable("call_sender_number", "");
                        }

                        if (callPayload.has("IsGroup")) tasker.setVariable("call_is_group", String.valueOf(callPayload.optBoolean("IsGroup")));
                        else tasker.setVariable("call_is_group", "false");

                        if (callPayload.has("ShutdownCauser")) tasker.setVariable("call_shutdown_causer", callPayload.optString("ShutdownCauser", ""));
                        else tasker.setVariable("call_shutdown_causer", "");

                        if (callPayload.has("TerminatedBy")) {
                            String terminatedBy = callPayload.optString("TerminatedBy", "");
                            if (terminatedBy.contains("@")) {
                                terminatedBy = terminatedBy.substring(0, terminatedBy.indexOf("@"));
                            }
                            tasker.setVariable("call_terminated_by", terminatedBy);
                        } else {
                            tasker.setVariable("call_terminated_by", "");
                        }

                        if (callPayload.has("AutoRejected")) tasker.setVariable("call_auto_rejected", String.valueOf(callPayload.optBoolean("AutoRejected")));
                        else tasker.setVariable("call_auto_rejected", "false");

                        if (callPayload.has("Type")) tasker.setVariable("call_type_message", callPayload.optString("Type", ""));
                        else tasker.setVariable("call_type_message", "");
                    }
                }
            }
        }
    }

    if (parseErrorMsg.length() == 0) {
        tasker.setVariable("parse_success", "true");
    } else {
        tasker.setVariable("parse_success", "false");
    }
    tasker.setVariable("parse_error", parseErrorMsg);

} catch (Exception e) {
    tasker.setVariable("parse_success", "false");
    tasker.setVariable("parse_error", e.getMessage());
    throw new JavaCodeException("Erro ao analisar JSON: " + e.getMessage());
}
